import test1 from "@/data/practice-tests/test-1.json";
import test2 from "@/data/practice-tests/test-2.json";
import test3 from "@/data/practice-tests/test-3.json";
import type { PracticeQuestion, PracticeTest, TestSlug } from "@/data/practice-tests/types";

export type { PracticeQuestion, PracticeTest, TestSlug };

/** The three public tests, in order. Generated by scripts/build-practice-tests.mjs. */
export const TESTS: PracticeTest[] = [test1, test2, test3] as PracticeTest[];

export const TEST_SLUGS = TESTS.map((t) => t.slug);

export function getTest(slug: string): PracticeTest | undefined {
  return TESTS.find((t) => t.slug === slug);
}

export function testPath(slug: TestSlug): string {
  return `/free-journeyman-electrician-practice-test/${slug}`;
}

export const TOTAL_FREE_QUESTIONS = TESTS.reduce((n, t) => n + t.questions.length, 0);
